import{_ as e,o as t,c as o,a2 as n}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":1782223980000}'),r={name:"glossary.md"};function i(l,a,h,d,c,s){return t(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><h2 id="agent" tabindex="-1">Agent <a class="header-anchor" href="#agent" aria-label="Permalink to &quot;Agent&quot;">​</a></h2><p>围绕目标规划步骤并调用工具的 AI 应用形态。Agent 的执行能力来自模型、工具接口、权限和控制流程，不等于模型拥有独立意识。</p><h2 id="alignment" tabindex="-1">Alignment <a class="header-anchor" href="#alignment" aria-label="Permalink to &quot;Alignment&quot;">​</a></h2><p>对齐。通过指令微调、偏好训练和安全约束等方法，让模型行为更符合人类目标、表达习惯和使用边界。对齐不能保证事实永远正确。</p><h2 id="attention" tabindex="-1">Attention <a class="header-anchor" href="#attention" aria-label="Permalink to &quot;Attention&quot;">​</a></h2><p>注意力机制。模型处理一个 Token 时，根据任务动态计算它与上下文中其他 Token 的关系权重。</p><h2 id="base-model" tabindex="-1">Base Model <a class="header-anchor" href="#base-model" aria-label="Permalink to &quot;Base Model&quot;">​</a></h2><p>基础模型。在 LLM 中通常指尚未完成特定指令对齐的通用预训练模型；在 AI 绘画中也用于说明 checkpoint 或 LoRA 所属的模型生态。</p><h2 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h2><p>保存某一训练阶段模型权重和相关状态的文件。AI 绘画中常见扩展名包括 <code>.safetensors</code> 和 <code>.ckpt</code>。</p><h2 id="cfg" tabindex="-1">CFG <a class="header-anchor" href="#cfg" aria-label="Permalink to &quot;CFG&quot;">​</a></h2><p>提示词引导强度。数值越高不代表越好，过高可能让画面变硬、变脏或结构异常。</p><h2 id="chunk" tabindex="-1">Chunk <a class="header-anchor" href="#chunk" aria-label="Permalink to &quot;Chunk&quot;">​</a></h2><p>文档切分后的片段。RAG 通常先把长文档拆成 Chunk，再建立索引和检索。切分过细会丢失上下文，过大则可能降低检索精度。</p><h2 id="clip" tabindex="-1">CLIP <a class="header-anchor" href="#clip" aria-label="Permalink to &quot;CLIP&quot;">​</a></h2><p>常见文本/图像编码模型。在 AI 绘画中经常负责把提示词编码成模型可用的信息。</p><h2 id="context-window" tabindex="-1">Context Window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context Window&quot;">​</a></h2><p>上下文窗口。模型单次推理可以处理的 Token 范围，通常包含系统指令、用户输入、历史消息、检索资料、工具结果和待生成内容。</p><h2 id="controlnet" tabindex="-1">ControlNet <a class="header-anchor" href="#controlnet" aria-label="Permalink to &quot;ControlNet&quot;">​</a></h2><p>结构控制模块，可以用姿势、线稿、深度图等条件控制生成结果。</p><h2 id="denoise" tabindex="-1">Denoise <a class="header-anchor" href="#denoise" aria-label="Permalink to &quot;Denoise&quot;">​</a></h2><p>去噪强度。在图生图和局部重绘中常见。数值越高，改动越大。</p><h2 id="embedding" tabindex="-1">Embedding <a class="header-anchor" href="#embedding" aria-label="Permalink to &quot;Embedding&quot;">​</a></h2><p>向量嵌入。把文本、图片或其他对象转换成可计算的向量表示，使语义相近的内容在向量空间中更接近。常用于搜索、推荐、聚类和 RAG。</p><h2 id="fine-tuning" tabindex="-1">Fine-tuning <a class="header-anchor" href="#fine-tuning" aria-label="Permalink to &quot;Fine-tuning&quot;">​</a></h2><p>微调。在预训练模型基础上继续使用特定数据训练，以改变模型的任务能力、格式、语气或领域行为。需要更新知识时不一定适合用微调，常应先评估 RAG。</p><h2 id="function-calling" tabindex="-1">Function Calling <a class="header-anchor" href="#function-calling" aria-label="Permalink to &quot;Function Calling&quot;">​</a></h2><p>模型按约定结构生成函数名和参数，由应用程序验证后调用真实函数。模型提出调用意图，程序负责权限、执行、错误处理和结果回传。</p><h2 id="hallucination" tabindex="-1">Hallucination <a class="header-anchor" href="#hallucination" aria-label="Permalink to &quot;Hallucination&quot;">​</a></h2><p>幻觉。模型生成了流畅、看似合理但缺少依据或事实错误的内容。检索、工具和 Prompt 可以降低风险，但仍需要来源与结果验证。</p><h2 id="inference" tabindex="-1">Inference <a class="header-anchor" href="#inference" aria-label="Permalink to &quot;Inference&quot;">​</a></h2><p>推理。使用训练完成的模型处理输入并生成预测或内容的阶段。普通用户的大多数模型调用都属于推理。</p><h2 id="latent" tabindex="-1">Latent <a class="header-anchor" href="#latent" aria-label="Permalink to &quot;Latent&quot;">​</a></h2><p>模型内部的压缩图像表示。扩散模型常在 latent 空间里生成，再通过 VAE 解码成图片。</p><h2 id="llm" tabindex="-1">LLM <a class="header-anchor" href="#llm" aria-label="Permalink to &quot;LLM&quot;">​</a></h2><p>Large Language Model，大语言模型。它根据上下文处理和生成 Token，可用于问答、写作、代码、信息抽取和工具调用，但不会自动保证事实正确。</p><h2 id="lora" tabindex="-1">LoRA <a class="header-anchor" href="#lora" aria-label="Permalink to &quot;LoRA&quot;">​</a></h2><p>Low-Rank Adaptation，低秩适配。通过训练少量附加参数调整模型行为。它既可用于 LLM 微调，也常用于给图像底模追加角色、画风、服装或概念。</p><h2 id="model-card" tabindex="-1">Model Card <a class="header-anchor" href="#model-card" aria-label="Permalink to &quot;Model Card&quot;">​</a></h2><p>模型卡。记录模型用途、训练背景、评估、限制、许可证和推荐用法的说明文档。下载或部署模型前应优先阅读。</p><h2 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h2><p>提示或任务说明。LLM Prompt 通常包含目标、上下文、约束和输出格式；图像 Prompt 常描述主体、场景、风格和构图，并可能区分正向与负向提示词。</p><h2 id="rag" tabindex="-1">RAG <a class="header-anchor" href="#rag" aria-label="Permalink to &quot;RAG&quot;">​</a></h2><p>Retrieval-Augmented Generation，检索增强生成。先从外部资料中检索相关片段，再把资料放入上下文供模型回答。</p><h2 id="sampler" tabindex="-1">Sampler <a class="header-anchor" href="#sampler" aria-label="Permalink to &quot;Sampler&quot;">​</a></h2><p>采样器，控制扩散模型去噪时的算法路径。</p><h2 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h2><p>调度器，控制去噪过程中噪声强度的变化方式。</p><h2 id="seed" tabindex="-1">Seed <a class="header-anchor" href="#seed" aria-label="Permalink to &quot;Seed&quot;">​</a></h2><p>随机种子。固定 seed 可以复现相近结果，便于比较参数。</p><h2 id="self-attention" tabindex="-1">Self-Attention <a class="header-anchor" href="#self-attention" aria-label="Permalink to &quot;Self-Attention&quot;">​</a></h2><p>自注意力。同一段输入内部的 Token 互相关注，从而形成包含上下文关系的新表示。</p><h2 id="text-encoder" tabindex="-1">Text Encoder <a class="header-anchor" href="#text-encoder" aria-label="Permalink to &quot;Text Encoder&quot;">​</a></h2><p>文本编码器，把提示词转换成模型可以理解的数字表示。</p><h2 id="textual-inversion" tabindex="-1">Textual Inversion <a class="header-anchor" href="#textual-inversion" aria-label="Permalink to &quot;Textual Inversion&quot;">​</a></h2><p>AI 绘画中的小型提示词嵌入，用少量学习到的向量触发特定概念或改善某类输出。它是 Embedding 的一种具体应用，不等同于通用语义 Embedding。</p><h2 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h2><p>模型处理文本的基本单位。Token 不一定等于一个汉字或英文单词，标点、空格和词片段也可能分别编码。</p><h2 id="transformer" tabindex="-1">Transformer <a class="header-anchor" href="#transformer" aria-label="Permalink to &quot;Transformer&quot;">​</a></h2><p>现代 LLM 的核心神经网络架构，通过 Attention、前馈网络、位置机制和多层堆叠处理序列信息。</p><h2 id="vae" tabindex="-1">VAE <a class="header-anchor" href="#vae" aria-label="Permalink to &quot;VAE&quot;">​</a></h2><p>变分自编码器。负责在 latent 和最终图片之间转换。</p><h2 id="vector-database" tabindex="-1">Vector Database <a class="header-anchor" href="#vector-database" aria-label="Permalink to &quot;Vector Database&quot;">​</a></h2><p>向量数据库。保存和检索 Embedding 的系统，常用于语义搜索和 RAG。它解决的是向量存储与相似度检索，不负责判断资料真假。</p><h2 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>AI 绘画图形界面。常用于指 Stable Diffusion WebUI，也可以泛指浏览器里的本地绘图界面。</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>工作流。把模型、数据、Prompt、工具和判断步骤按固定顺序连接起来的执行流程；在 ComfyUI 中通常表现为节点图。</p>',69)])])}const b=e(r,[["render",i]]);export{p as __pageData,b as default};
